import {engineeringForces} from './physics.js';
const root=document.querySelector('#engineering-content');
root.innerHTML=`<div class="engineering-intro"><div><div class="eyebrow">ENGINEERING / FROM COMPONENT TO EQUATION</div><h2>Understand what the car is doing.</h2><p>Change explicit assumptions and inspect the relationships. These examples are not measured RB19–RB22 coefficients, a CFD solver, a tyre model or a lap-time prediction.</p></div><a class="quiet" href="https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/drag-equation/" target="_blank" rel="noopener">NASA / aerodynamic equations ↗</a></div>
<div class="engineering-grid"><article class="physics-controls"><h3>Illustrative operating point</h3><div class="eyebrow">USER-SET ASSUMPTIONS / SI UNITS</div><label for="physics-speed">SPEED <output id="speed-output">200 km/h</output></label><input id="physics-speed" type="range" min="20" max="360" step="1" value="200"><div class="physics-inputs"><label>MASS / kg<input id="physics-mass" type="number" min="300" max="2000" value="800"></label><label>AIR DENSITY / kg/m³<input id="physics-rho" type="number" min=".3" max="2" step=".025" value="1.225"></label><label>REFERENCE AREA / m²<input id="physics-area" type="number" min=".1" max="10" step=".1" value="1.5"></label><label>DRAG COEFFICIENT / Cᴅ<input id="physics-cd" type="number" min="0" max="5" step=".1" value="1"></label><label>DOWNFORCE COEFF. / |Cʟ|<input id="physics-cl" type="number" min="0" max="10" step=".1" value="3"></label><label>CORNER RADIUS / m<input id="physics-radius" type="number" min="10" max="2000" value="100"></label><label>SIMPLIFIED FRICTION / μ<input id="physics-mu" type="number" min=".1" max="3" step=".1" value="1.5"></label><label>BODY SIDESLIP / degrees<input id="physics-beta" type="number" min="-30" max="30" step="1" value="5"></label></div><p id="physics-error" role="status"></p><p class="small">The coefficient and area must use the same convention. μ is held constant here; real tyres exhibit load, temperature, slip and transient dependence.</p></article>
<article id="physics-aero" class="physics-topic"><div class="eyebrow">01 / AERODYNAMICS</div><h3>Speed makes aerodynamic forces grow quadratically.</h3><div class="formula">q = ½ρv²<br>D = q C<sub>D</sub> A<br>F<sub>down</sub> = q |C<sub>L</sub>| A<br>P<sub>drag</sub> = Dv</div><div id="aero-values" class="physics-values"></div><p>Doubling speed multiplies the force by four at unchanged coefficients and density. Drag power then grows by a factor of eight. We use a positive downforce magnitude; lift sign conventions differ.</p><a href="https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/lift-equation-2/" target="_blank" rel="noopener">NASA / lift equation and reference quantities ↗</a></article>
<article id="physics-tyres" class="physics-topic"><div class="eyebrow">02 / CORNERING & LOAD</div><h3>Cornering demand competes with the available tyre force.</h3><div class="formula">a<sub>y</sub> = v² / R<br>F<sub>y,required</sub> = m v² / R<br>F<sub>limit,illustrative</sub> = μ(mg + F<sub>down</sub>)</div><div id="tyre-values" class="physics-values"></div><div class="force-meter"><span id="force-fill"></span></div><p id="force-context"></p><p>This is a whole-car force budget at constant radius and speed. It ignores tyre load sensitivity, combined braking/traction, load transfer, banking, suspension kinematics and changing aero balance. Exceeding the budget is a warning within this example, not a validated prediction of a spin.</p><a href="https://aws.amazon.com/sports/f1/" target="_blank" rel="noopener">F1 Insights / telemetry-based tyre and balance analysis ↗</a></article>
<article id="physics-slip" class="physics-topic"><div class="eyebrow">03 / SIDESLIP ≠ TYRE SLIP ANGLE</div><h3>Pointing one way and moving another.</h3><div id="slip-diagram"></div><div class="formula">β = atan2(v<sub>y,body</sub>, v<sub>x,body</sub>)</div><p>β is the vehicle body’s velocity angle relative to its longitudinal axis. A tyre slip angle α instead compares the wheel’s orientation with the local velocity at that wheel. Steering, yaw rate and the wheel’s location affect α.</p><p>Drift involves substantial sideslip and tyre sliding. It is not equivalent to aerodynamic drag, nor does a larger slip angle always generate more lateral force. Neither β nor α can be recovered from a lap-average speed alone.</p><a href="https://aws.amazon.com/sports/f1/" target="_blank" rel="noopener">Read how actual telemetry supports slip-angle estimates ↗</a></article>
<article class="physics-topic"><div class="eyebrow">04 / HOW TO READ THE TRACK COMPARISON</div><h3>Observed lap performance is not an intrinsic car speed.</h3><p>Race results report what a driver and car achieved in one event. Track configuration, tyres, fuel, weather, traffic and strategy all affect the lap. Compare the same circuit and season when possible, and still preserve that context.</p><p>See on Track uses Jolpica race results. The playback moves uniformly around a reference map using the observed lap duration; it is not a reproduction of the original racing line or telemetry.</p><a href="https://github.com/jolpica/jolpica-f1/blob/main/docs/endpoints/results.md" target="_blank" rel="noopener">Jolpica / race-result field definitions ↗</a><button class="quiet" id="physics-to-track">Open See on Track ↗</button></article></div>`;
const $=s=>document.querySelector(s),fields=['mass','rho','area','cd','cl','radius','mu','beta'];
function update(){for(const id of fields){const input=$('#physics-'+id);if(!input.checkValidity()||input.value===''){$('#physics-error').textContent='Enter a valid value for '+id+'.';return}}$('#physics-error').textContent='';const values=Object.fromEntries(fields.map(id=>[id,Number($('#physics-'+id).value)]));const forces=engineeringForces({...values,speedKph:Number($('#physics-speed').value),betaDeg:values.beta});$('#speed-output').textContent=$('#physics-speed').value+' km/h';$('#aero-values').innerHTML=`<div><b>${forces.drag.toFixed(0)} N</b><span>drag</span></div><div><b>${forces.downforce.toFixed(0)} N</b><span>downforce magnitude</span></div><div><b>${forces.dragPowerKw.toFixed(1)} kW</b><span>power against aero drag</span></div>`;$('#tyre-values').innerHTML=`<div><b>${forces.lateralG.toFixed(2)} g</b><span>required lateral acceleration</span></div><div><b>${forces.lateralForce.toFixed(0)} N</b><span>required lateral force</span></div><div><b>${forces.friction.toFixed(0)} N</b><span>illustrative force budget</span></div>`;$('#force-fill').style.width=Math.min(forces.utilization,1)*100+'%';$('#force-fill').style.background=forces.utilization>1?'#eaa184':'#83bbc5';$('#force-context').textContent=(forces.utilization*100).toFixed(0)+'% of this simplified budget.';const angle=values.beta,dx=Math.sin(forces.betaRad)*95,dy=-Math.cos(forces.betaRad)*95;$('#slip-diagram').innerHTML=`<svg viewBox="0 0 310 180" role="img" aria-label="Illustrative body heading and velocity angle"><defs><marker id="slip-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8ccad2"/></marker></defs><rect x="129" y="95" width="42" height="70" rx="8" fill="#556c7c" stroke="#b3c9d3"/><path d="M150 130V20" stroke="#dcd4a0" stroke-dasharray="4 4"/><path d="M150 130L${150+dx} ${130+dy}" stroke="#8ccad2" stroke-width="2" marker-end="url(#slip-arrow)"/><text x="30" y="22" fill="#dcd4a0">body heading</text><text x="185" y="60" fill="#8ccad2">velocity</text><text x="190" y="145" fill="#c9d8df">β = ${angle}°</text></svg>`}
root.addEventListener('input',update);update();$('#physics-to-track').onclick=()=>document.querySelector('nav [data-tab="track"]').click();
window.addEventListener('apex-engineering',event=>{document.querySelector('nav [data-tab="engineering"]').click();const topic=event.detail?.topic||'aero';requestAnimationFrame(()=>$('#physics-'+topic)?.scrollIntoView({behavior:'smooth',block:'center'}))});
